import React, { useState, useEffect, useCallback, Suspense } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Environment, useGLTF } from '@react-three/drei';
import styles from './HomePage.module.css';

// Компонент для загрузки 3D-модели автомобиля
const CarModel = ({ url, color }) => {
  const { scene } = useGLTF(url);
  // Если хотите применить цвет, можно пройтись по материалам, но оставим как есть
  return <primitive object={scene} scale={[1.2, 1.2, 1.2]} position={[0, -0.5, 0]} />;
};

// Заглушка на случай, если модель не загрузится – показываем цветной фон
const FallbackCar = ({ color }) => (
  <div style={{
    width: '100%',
    height: '100%',
    background: `radial-gradient(circle at center, ${color} 0%, #000 70%)`,
    position: 'absolute',
    inset: 0,
  }} />
);

// Слайды с описанием: тип, текст, и параметры 3D-модели
const slides = [
  {
    id: 0,
    type: 'welcome',
    title: 'Искусство движения',
    subtitle: 'Эксклюзивные автомобили для тех, кто ценит совершенство',
    is3D: false,
    bg: 'https://images.pexels.com/photos/170811/pexels-photo-170811.jpeg?auto=compress&cs=tinysrgb&w=1350&h=900&dpr=2',
  },
  {
    id: 1,
    type: 'car',
    model: 'BMW M8 Gran Coupe',
    price: 17500000,
    is3D: true,
    modelUrl: 'https://vazxmixjsiawhcamofhs.supabase.co/storage/v1/object/public/models/bmw-m4/model.gltf', // Пример модели BMW (замените при необходимости)
    color: '#1e3a8a',
  },
  {
    id: 2,
    type: 'car',
    model: 'Porsche 911 Turbo S',
    price: 22000000,
    is3D: true,
    modelUrl: 'https://vazxmixjsiawhcamofhs.supabase.co/storage/v1/object/public/models/porsche-911/model.gltf', // Пример модели Porsche
    color: '#b91c1c',
  },
  {
    id: 3,
    type: 'car',
    model: 'Range Rover Sport SV',
    price: 18500000,
    is3D: true,
    modelUrl: 'https://vazxmixjsiawhcamofhs.supabase.co/storage/v1/object/public/models/range-rover/model.gltf', // Пример Range Rover
    color: '#2d5a27',
  },
  {
    id: 4,
    type: 'car',
    model: 'Mercedes-AMG GT 63',
    price: 19500000,
    is3D: true,
    modelUrl: 'https://vazxmixjsiawhcamofhs.supabase.co/storage/v1/object/public/models/mercedes-amg/model.gltf', // Пример Mercedes
    color: '#4a148c',
  },
];

const HomePage = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);

  const goToSlide = useCallback((index) => {
    if (index >= 0 && index < slides.length && !isTransitioning) {
      setIsTransitioning(true);
      setCurrentSlide(index);
    }
  }, [isTransitioning]);

  const handleWheel = useCallback((e) => {
    e.preventDefault();
    if (isTransitioning) return;
    if (e.deltaY > 0) {
      goToSlide(currentSlide + 1);
    } else if (e.deltaY < 0) {
      goToSlide(currentSlide - 1);
    }
  }, [currentSlide, goToSlide, isTransitioning]);

  useEffect(() => {
    const timeout = setTimeout(() => setIsTransitioning(false), 900);
    return () => clearTimeout(timeout);
  }, [currentSlide]);

  useEffect(() => {
    window.addEventListener('wheel', handleWheel, { passive: false });
    return () => window.removeEventListener('wheel', handleWheel);
  }, [handleWheel]);

  return (
    <div className={styles.container}>
      <div className={styles.slidesWrapper}>
        <AnimatePresence mode="wait">
          <motion.div
            key={currentSlide}
            className={styles.slide}
            initial={{ opacity: 0, scale: 1.02 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.98 }}
            transition={{ duration: 0.8, ease: 'easeInOut' }}
          >
            {/* Фон для обычного слайда */}
            {!slides[currentSlide].is3D && (
              <div className={styles.bgImage} style={{ backgroundImage: `url(${slides[currentSlide].bg})` }} />
            )}

            {/* 3D-сцена для машин */}
            {slides[currentSlide].is3D && (
              <div className={styles.canvasWrapper}>
                <Suspense fallback={<FallbackCar color={slides[currentSlide].color} />}>
                  <Canvas
                    camera={{ position: [7, 2, 3], fov: 45 }}
                    style={{ background: 'radial-gradient(circle at center, #1a1a2e 0%, #0f0f1a 100%)' }}
                  >
                    <ambientLight intensity={0.5} />
                    <spotLight position={[5, 5, 5]} angle={0.3} penumbra={1} intensity={2} color="white" />
                    <pointLight position={[-5, 3, -5]} intensity={1.5} color="#8a2be2" />
                    <pointLight position={[0, -2, 3]} intensity={1} color="#4a148c" />
                    <Suspense fallback={null}>
                      <CarModel url={slides[currentSlide].modelUrl} color={slides[currentSlide].color} />
                      <Environment preset="city" />
                      <OrbitControls
                        enableZoom={false}
                        enablePan={false}
                        autoRotate
                        autoRotateSpeed={1.5}
                        maxPolarAngle={Math.PI / 2.2}
                        minPolarAngle={Math.PI / 2.5}
                      />
                    </Suspense>
                  </Canvas>
                </Suspense>
                <div className={styles.overlay} />
              </div>
            )}

            {/* Общий оверлей и текст */}
            {(slides[currentSlide].type === 'welcome' || !slides[currentSlide].is3D) && <div className={styles.overlay} />}
            <div className={styles.content}>
              {slides[currentSlide].type === 'welcome' ? (
                <>
                  <h1>{slides[currentSlide].title}</h1>
                  <p>{slides[currentSlide].subtitle}</p>
                  <Link to="/catalog" className={styles.cta}>Смотреть каталог</Link>
                </>
              ) : (
                <>
                  <h2>{slides[currentSlide].model}</h2>
                  <p className={styles.price}>от {slides[currentSlide].price.toLocaleString()} ₽</p>
                  <Link to="/catalog" className={styles.cta}>Подробнее</Link>
                </>
              )}
            </div>
          </motion.div>
        </AnimatePresence>
      </div>

      <div className={styles.dots}>
        {slides.map((_, idx) => (
          <button
            key={idx}
            className={`${styles.dot} ${idx === currentSlide ? styles.activeDot : ''}`}
            onClick={() => goToSlide(idx)}
            aria-label={`Слайд ${idx + 1}`}
          />
        ))}
      </div>
    </div>
  );
};

export default HomePage;
